  "x125_y50": {
    "coordinate": "x125_y50",
    "biome": "Hills",
    "kingdom": "Dwynbroch",
    "zone": "City",
    "cityVillage": "Morvarth",
    "description": "From 'Mor,' meaning sea, and 'Varth,' signifying a hill. A coastal city known for its commanding views over the sea from elevated grounds.",
    "establishments": [
      {
        "name": "The Highland Meadery",
        "type": "Tavern",
        "description": "A long-benched hall perched on the coastal bluff, famous for reserve mead brewed with sea-kelp and highland heather."
      },
      {
        "name": "The Clifftop Lodge",
        "type": "Inn",
        "description": "A solid stone inn at the city's highest point, where windows look out over the sea and rooms are cold but spectacular."
      },
      {
        "name": "Morvarth Harbour Market",
        "type": "Market",
        "description": "A dockside market dealing in salted fish, rope, navigational instruments, and whatever the last ship brought in."
      },
      {
        "name": "The Sea-Chain Smithy",
        "type": "Blacksmith",
        "description": "A coastal forge specialising in anchor-chain, harpoon heads, and weapons reinforced against saltwater corrosion."
      },
      {
        "name": "The Morvarth Barracks",
        "type": "Barracks",
        "description": "A squat hill-fort garrisoned by Dwynbroch's coastal watch, tasked with signalling invasion and keeping the harbour road clear."
      }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
