  "x150_y450": {
    "coordinate": "x150_y450",
    "biome": "Plains",
    "kingdom": "Ardrenhold",
    "zone": "CapitalCity",
    "cityVillage": "Ardrenkeep",
    "description": "Ardrenhold’s capital. A fortified and well-guarded city housing Ardrenhold’s main keep and the throne of their noble king.",
    "establishments": [
      {
        "name": "The Knight's Rest",
        "type": "Inn",
        "description": "A historic inn famous for being a meeting place of legendary knights and adventurers."
      },
      {
        "name": "The Royal Falconry",
        "type": "Aviary",
        "description": "A majestic aviary where the finest falcons are trained for hunting and messaging."
      },
      {
        "name": "Ardren Barracks",
        "type": "Barracks",
        "description": "The king's standing garrison, its walls plastered with service rosters and battle honours going back four generations."
      },
      {
        "name": "The Crown's Scales",
        "type": "Market",
        "description": "A sprawling open market where merchants from across the plains bring grain, livestock, and finished goods under royal licence."
      },
      {
        "name": "The Gilded Spur",
        "type": "Blacksmith",
        "description": "Renowned for armour and horseshoes bearing the Ardrenhold crest, forged to outlast a decade of campaign."
      },
      {
        "name": "Temple of the Steadfast",
        "type": "Temple",
        "description": "A solemn stone temple honouring the patron of oaths and duty, frequented by knights before and after battle."
      },
      {
        "name": "The Warden's Guild",
        "type": "Guild",
        "description": "Headquarters of Ardrenhold's mercenary wardens, where contracts are posted and blade-skills are quietly traded."
      },
      {
        "name": "Aldric's Apothecary",
        "type": "Apothecary",
        "description": "A well-stocked shop supplying the castle infirmary and discerning travellers with salves, tonics, and antidotes."
      }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
