  "x250_y75": {
    "coordinate": "x250_y75",
    "biome": "Lake",
    "kingdom": "Dwynbroch",
    "zone": "City",
    "cityVillage": "Lochvale",
    "description": "",
    "establishments": [
      {
        "name": "The Drowned Anchor",
        "type": "Inn",
        "description": "A low-ceilinged lakeside inn that smells of fish and woodsmoke. The beds are narrow but dry, which is more than can be said for the dock outside."
      },
      {
        "name": "Lochvale Market",
        "type": "Market",
        "description": "An open-air market near the water's edge. Traders sell everything from cured fish and rope to blades and boot leather."
      },
      {
        "name": "The Ironhook Smithy",
        "type": "Blacksmith",
        "description": "Run by a broad-shouldered woman who claims to have worked a forge in every kingdom. Her prices reflect this confidence."
      },
      {
        "name": "Temple of the Tide",
        "type": "Temple",
        "description": "A modest stone building at the shore, maintained by a small order of clerics who tend to sailors and those who work the lake."
      },
      {
        "name": "The Fishmonger's Quay",
        "type": "Shop",
        "description": "Half shop, half dock. The owner sells fresh catch, smoked provisions, and the occasional rumour about what the nets have pulled up lately."
      },
      {
        "name": "Lochvale Arena",
        "type": "Arena",
        "description": "A well-maintained fighting pit that draws crowds on market days. Local fighters compete for coin and reputation."
      }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
