  "x275_y275": {
    "coordinate": "x275_y275",
    "biome": "River",
    "kingdom": "Dwynbroch",
    "zone": "CapitalCity",
    "cityVillage": "Aberwyn",
    "description": "Combining 'Aber,' for the mouth of a river, with 'Wyn,' meaning fair or white. A city by the river mouth, known for its picturesque beauty.",
    "establishments": [
        {
            "name": "The Crown & Stag Inn",
            "type": "Inn",
            "description": "The finest inn in Dwynbroch, reserved for nobles and wealthy merchants."
        },
        {
            "name": "The Clan Hall Tavern",
            "type": "Tavern",
            "description": "A vast mead-hall where clan leaders negotiate and celebrate."
        },
        {
            "name": "Royal Forge of Aberwyn",
            "type": "Blacksmith",
            "description": "Produces weapons and armour for the highland clans under royal charter."
        },
        {
            "name": "Aberwyn Grand Market",
            "type": "Market",
            "description": "A permanent market district sprawling across four city blocks."
        },
        {
            "name": "Temple of the Ancient Oak",
            "type": "Temple",
            "description": "A sacred forest temple at the city's heart, tended by druids."
        },
        {
            "name": "Aberwyn Alchemical Academy",
            "type": "Alchemist",
            "description": "The finest purveyor of magical compounds north of the mountains."
        },
        {
            "name": "Merchant Guild of Aberwyn",
            "type": "Guild Hall",
            "description": "Controls all trade agreements within Dwynbroch."
        },
        {
            "name": "Royal Stables",
            "type": "Stable",
            "description": "Horses bred for endurance in highland terrain."
        },
        {
            "name": "Aberwyn Archive",
            "type": "Library",
            "description": "A stone library housing centuries of clan histories and treaties."
        },
        {
            "name": "Clan Council Hall",
            "type": "Town Hall",
            "description": "Where the High Chieftain holds court and the clans convene."
        },
        {
            "name": "The Iron Ring",
            "type": "Arena",
            "description": "A fighting pit where champions prove themselves."
        }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
