  "x300_y325": {
    "coordinate": "x300_y325",
    "biome": "Lake",
    "kingdom": "Sivanrift",
    "zone": "City",
    "cityVillage": "Iriandel",
    "description": "Constructed along the cliffside above the Echoing Canyons, this city uses natural acoustics in both art and defense.",
    "establishments": [
        {
            "name": "The Silver Spire Inn",
            "type": "Inn",
            "description": "Elegantly decorated; a favourite of elven travellers and diplomats."
        },
        {
            "name": "The Whisper & Vine",
            "type": "Tavern",
            "description": "Quiet conversations over fine wine; not a place for raised voices."
        },
        {
            "name": "Iriandel Craftwork",
            "type": "Blacksmith",
            "description": "Produces exquisitely finished blades and decorated armour."
        },
        {
            "name": "Iriandel Exchange",
            "type": "Market",
            "description": "A refined trading hall where goods of quality command premium prices."
        },
        {
            "name": "Temple of the Starlit Path",
            "type": "Temple",
            "description": "Dedicated to celestial guidance and scholarly wisdom."
        },
        {
            "name": "House of Essences",
            "type": "Alchemist",
            "description": "Rare components and refined potions; prices are steep but quality absolute."
        },
        {
            "name": "Silven & Sons",
            "type": "Tailor",
            "description": "The finest cloaks, formal wear, and travelling attire in the Rift."
        }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
  "x300_y350": {
    "coordinate": "x300_y350",
    "biome": "Coastal",
    "kingdom": "Sivanrift",
    "zone": "City",
    "cityVillage": "Aurelwyn",
    "description": "A port city nestled along a crescent bay, thriving on trade in exotic wines, enchanted textiles, and rare herbs. Elven-designed sea walls arc around a harbour of silver-sailed vessels.",
    "establishments": [
      {
        "name": "The Crescent Moon Inn",
        "type": "Tavern",
        "description": "A graceful harbour-side inn where merchants and sailors share sea tales over spiced wine."
      },
      {
        "name": "The Silver Sail Inn",
        "type": "Inn",
        "description": "A merchant inn overlooking the bay, decorated with silver-leaf nautical charts and serving wine from the city's own vineyards."
      },
      {
        "name": "Aurelwyn Harbour",
        "type": "Harbour",
        "description": "Silver-sailed vessels load and unload enchanted textiles, exotic herbs, and rare dyes at these elegantly carved elven docks."
      },
      {
        "name": "The Bay Market",
        "type": "Market",
        "description": "A sweeping market along the crescent waterfront, where import goods from across the sea are assessed and sold under guild charter."
      },
      {
        "name": "The Sea-Warden Guild",
        "type": "Guild",
        "description": "A traders' and sailors' guild that controls harbour access, vessel licensing, and arbitrates disputes between merchant houses."
      }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
