    "pointsOfInterest": [{"name":"The Eldertree Threshold","type":"ancient_ruins","description":"A stone archway standing alone in the forest with no wall attached. The lintel is carved with two faces looking in opposite directions. Animals will not walk through it, and the air on the far side is measurably cooler."}],
