  "x375_y350": {
    "coordinate": "x375_y350",
    "biome": "Hills",
    "kingdom": "Sivanrift",
    "zone": "CapitalCity",
    "cityVillage": "Myrthill",
    "description": "A radiant city of silverwood towers and marble courtyards, centered around the Grand Gardens. A symbol of harmony between races—at least on the surface.",
    "establishments": [
      {
        "name": "The Grand Gardens of Sivanrift",
        "type": "Other",
        "description": "The gardens in the capital city’s town square, where the elves there grow rare plants found nowhere else in the world."
      },
      {
        "name": "The Silver Bough Inn",
        "type": "Inn",
        "description": "Built around a living silverwood tree, this graceful inn offers rooms scented with blossoms and lit by bioluminescent moss."
      },
      {
        "name": "The Council Hall Tavern",
        "type": "Tavern",
        "description": "A public drinking-hall adjacent to the Grand Council, where dignitaries argue over wine until the council reconvenes."
      },
      {
        "name": "Myrthill Barracks",
        "type": "Barracks",
        "description": "The joint garrison of Sivanrift’s city-guard, its marble courtyard used for drills that visiting dignitaries pretend not to watch."
      },
      {
        "name": "The Lorekeeper’s Hall",
        "type": "Library",
        "description": "A multi-storey archive of parchments, botanical records, and diplomatic treaties kept by three generations of elven scholars."
      },
      {
        "name": "The Harmony Guild",
        "type": "Guild",
        "description": "A multi-race guild mediating trade disputes and licensing craftworkers throughout Sivanrift."
      },
      {
        "name": "Myrenne’s Herbalist",
        "type": "Herbalist",
        "description": "A fragrant stall near the gardens where rare poultices, pressed flowers, and restorative tinctures are sold by a sharp-eyed half-elf."
      },
      {
        "name": "The Cartographers’ Circle",
        "type": "Cartographer",
        "description": "Sivanrift’s guild of map-makers, whose charts of the known world are traded and commissioned by explorers across the continent."
      }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
