  "x475_y150": {
    "coordinate": "x475_y150",
    "biome": "Mountains",
    "kingdom": "Wistravael",
    "zone": "CapitalCity",
    "cityVillage": "Durkendal",
    "description": "The capital city, built beneath the Mountain of Stars. Known for its vast observatory and underground council halls.",
    "establishments": [
      {
        "name": "The Guilded Anvil",
        "type": "Blacksmith",
        "description": "A famous dwarven blacksmith shop known for crafting exquisite jewelry and decorative metalwork."
      },
      {
        "name": "The Mountain's Hearth",
        "type": "Inn",
        "description": "Carved into the living rock beneath the city's main tower, this inn is perpetually warm and smells of forge-smoke and pine."
      },
      {
        "name": "The Observatory Taproom",
        "type": "Tavern",
        "description": "Nestled below the famous observatory, astronomers and off-duty guards drink starlight mead and debate the cosmos."
      },
      {
        "name": "Council Hall Barracks",
        "type": "Barracks",
        "description": "A fortified garrison protecting the underground council chambers, staffed by Wistravael's most trusted elite soldiers."
      },
      {
        "name": "Starspire Library",
        "type": "Library",
        "description": "A deep-rock archive containing astronomical charts, runic histories, and classified council minutes sealed in iron cylinders."
      },
      {
        "name": "The Durkendal Exchange",
        "type": "Market",
        "description": "A subterranean bazaar lit by witchlight where traders from the surface world barter with Wistravael's mountain clans."
      },
      {
        "name": "The Arcane Spire",
        "type": "Mage Tower",
        "description": "A tower of black granite where Wistravael's council-mages study celestial magic and train apprentices in starfire arts."
      },
      {
        "name": "The Vaultkeeper's Guild",
        "type": "Guild",
        "description": "An association of enchanters and scholars who protect, catalogue, and appraise the magical artefacts recovered from the deep."
      }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
