  "x500_y150": {
    "coordinate": "x500_y150",
    "biome": "Mountains",
    "kingdom": "Wistravael",
    "zone": "City",
    "cityVillage": "Vordrun Keep",
    "description": "A heavily fortified city carved into a sheer cliff, guarding the pass into the inner kingdom. The first—and last—line of defense.",
    "establishments": [
      {
        "name": "The Celestial Observatory",
        "type": "Other",
        "description": "A forgotten observatory atop the highest peak. Here, a celestial map reveals the location of a hidden star metal, a rare substance that can be forged into a weapon of unparalleled sharpness and durability."
      },
      {
        "name": "The Passguard Inn",
        "type": "Inn",
        "description": "The only lodging inside Vordrun's walls; austere, monitored, and grateful to any guest who does not cause trouble."
      },
      {
        "name": "The Garrison Tap",
        "type": "Tavern",
        "description": "A soldiers' tavern attached to the fort's mess hall, accessible to civilians willing to tolerate the scrutiny of off-duty guards."
      },
      {
        "name": "The Cliff-Face Forge",
        "type": "Blacksmith",
        "description": "A military smithy cut into the sheer wall, producing reinforced armour and siege-repair tools for the keep's defenders."
      },
      {
        "name": "Vordrun Barracks",
        "type": "Barracks",
        "description": "The fortress garrison that guards the mountain pass; its soldiers rotate on strict watch cycles that have held for two centuries."
      }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
