  "x575_y400": {
    "coordinate": "x575_y400",
    "biome": "Mountains",
    "kingdom": "Feldarún",
    "zone": "City",
    "cityVillage": "Khúralgron",
    "description": " grand forge-city carved into a volcanic caldera, its molten rivers fuel legendary smithies day and night.",
    "establishments": [
      {
        "name": "The Ironbell",
        "type": "Blacksmith",
        "description": "A renowned forge where master blacksmiths create legendary dwarven weapons and artifacts."
      },
      {
        "name": "The Caldera Inn",
        "type": "Inn",
        "description": "Built over a sealed lava duct, this inn is perpetually warm; guests are advised not to open the floor vents unattended."
      },
      {
        "name": "The Ash & Ember Tavern",
        "type": "Tavern",
        "description": "A soot-dark tavern where smiths come off shift to drink black-iron stout and argue about alloy ratios."
      },
      {
        "name": "The Caldera Market",
        "type": "Market",
        "description": "A circular market around the old lava channel where finished metalwork, ore contracts, and forge-tools are auctioned."
      },
      {
        "name": "Khúralgron Barracks",
        "type": "Barracks",
        "description": "A fireproof fortress garrison of heat-hardened dwarven soldiers who defend the city's forge-works against raid and theft."
      },
      {
        "name": "The Smith's Guild",
        "type": "Guild",
        "description": "The guild that controls craft standards for Khúralgron's smiths, issues journeyman marks, and holds monopoly on caldera steel."
      }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
