  "x600_y350": {
    "coordinate": "x600_y350",
    "biome": "Mountains",
    "kingdom": "Feldarún",
    "zone": "CapitalCity",
    "cityVillage": "Darakthul",
    "description": "Known as the “Iron Crown of the East,” this city is built atop a jagged peak and ringed with defensive battlements of obsidian.",
    "establishments": [
      {
        "name": "The Emberheart Tavern",
        "type": "Tavern",
        "description": "Famous for its fiery spiced cuisine and warm, welcoming hearth, but weary of outsiders and non-dwarves."
      },
      {
        "name": "The Black Summit Inn",
        "type": "Inn",
        "description": "A fortified lodging hewn from obsidian-streaked stone, offering cold rooms and strong drink to those who make the climb."
      },
      {
        "name": "The Ironclad Barracks",
        "type": "Barracks",
        "description": "A hulking fortress within a fortress, housing Darakthul's elite obsidian guard who patrol the city's battlements day and night."
      },
      {
        "name": "The Smelter's Row",
        "type": "Blacksmith",
        "description": "A row of forges where Feldarún's master smiths produce obsidian-edged weapons traded across the mountain kingdoms."
      },
      {
        "name": "The Iron Crown Market",
        "type": "Market",
        "description": "A windswept mountain marketplace where ore, armour, and warband contracts are traded in the shadow of the battlements."
      },
      {
        "name": "The Stone Vault",
        "type": "Library",
        "description": "A deep-cut archive holding Feldarún's military history, siege maps, and forbidden texts on forbidden metal-lore."
      },
      {
        "name": "The Warlord's Guild",
        "type": "Guild",
        "description": "Feldarún's warrior-merchant guild, where war contracts are signed, mercenaries vetted, and arms deals sealed with iron handshakes."
      },
      {
        "name": "The Peak Alchemist",
        "type": "Alchemist",
        "description": "A mountain-top alchemist selling explosive compounds, flame-oil, and fortifying draughts favoured by soldiers and miners alike."
      }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
