  "x675_y50": {
    "coordinate": "x675_y50",
    "biome": "Mountains",
    "kingdom": "Rendarost",
    "zone": "CapitalCity",
    "cityVillage": "Kragmoor",
    "description": "A fortress-city tunneled into a frozen cliff face, where frost-forged weapons are made and sold only to kin.",
    "establishments": [
      {
        "name": "The Great Dwarven Archives",
        "type": "Library",
        "description": "A massive frost-hewn archive cut into Kragmoor's deepest tunnels, holding records of every clan, vault, and battle since the Founding."
      },
      {
        "name": "The Frozen Gate Inn",
        "type": "Inn",
        "description": "A thick-walled refuge of carved ice and stone where travellers thaw by a roaring central furnace before the next push north."
      },
      {
        "name": "The Frost Forge",
        "type": "Blacksmith",
        "description": "Rendarost's premier weaponsmithy, where frost-forged steel is hammered and quenched in glacial meltwater for unrivalled hardness."
      },
      {
        "name": "The Glacier Barracks",
        "type": "Barracks",
        "description": "A carved cliff-garrison housing Kragmoor's elite frost-warriors, who train in sub-zero conditions from childhood."
      },
      {
        "name": "The Icevein Market",
        "type": "Market",
        "description": "A covered market inside a natural cavern where ore, preserved game, pelts, and cold-steel tools change hands by torchlight."
      },
      {
        "name": "The Runecutter's Guild",
        "type": "Guild",
        "description": "The dwarven guild that registers rune-carvers, authorises inscriptions, and guards the monopoly on Rendarost's runic sealing arts."
      },
      {
        "name": "The Deep Alchemist",
        "type": "Alchemist",
        "description": "A cramped tunnel-shop selling frost-retardants, anti-hypothermia draughts, and explosive compounds for mine-clearing operations."
      }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
