  "x725_y400": {
    "coordinate": "x725_y400",
    "biome": "River",
    "kingdom": "Feldarún",
    "zone": "City",
    "cityVillage": "Vurndrim",
    "description": "A city famed for its echoing halls and deep-drum festivals, where every corridor carries the sound of ancient songs.",
    "establishments": [
        {
            "name": "The Vurndrim Tower Inn",
            "type": "Inn",
            "description": "A five-floor inn in a converted fortification."
        },
        {
            "name": "The Deep Vein",
            "type": "Tavern",
            "description": "Named for the ore-rich mines below; popular with off-shift miners."
        },
        {
            "name": "Vurndrim Iron House",
            "type": "Blacksmith",
            "description": "Multiple forges producing large quantities of iron goods."
        },
        {
            "name": "Vurndrim Market Hall",
            "type": "Market",
            "description": "A permanent covered market dealing in metal goods and ore."
        },
        {
            "name": "Temple of Endurance",
            "type": "Temple",
            "description": "A stoic deity's temple; prized by miners, soldiers, and labourers."
        },
        {
            "name": "Vurndrim Miners' Association",
            "type": "Guild Hall",
            "description": "Manages all quarrying and smelting contracts in the region."
        },
        {
            "name": "Vurndrim Stables",
            "type": "Stable",
            "description": "Draft horses and mules suited to underground cartage."
        },
        {
            "name": "Vurndrim Guild Hall",
            "type": "Town Hall",
            "description": "Where all major commercial decisions for the city are made."
        }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
