  "x750_y550": {
    "coordinate": "x750_y550",
    "biome": "Coastal",
    "kingdom": "Brythwen",
    "zone": "City",
    "cityVillage": "Windhall",
    "description": "Suggesting a place exposed to the elements, a city known for its strategic location and resilient people.",
    "establishments": [
      {
        "name": "Windhall Port",
        "type": "Harbour",
        "description": "A coastal harbour perpetually battered by sea-gales, where Brythwen's most weathered sailors load and unload cargo under iron skies."
      },
      {
        "name": "Windhall Marketplace",
        "type": "Market",
        "description": "A seafront market sheltered behind stone windbreaks where salt-fish, rope, and salvage goods are sold at blunt prices."
      },
      {
        "name": "The Gale's End Inn",
        "type": "Inn",
        "description": "A broad-beamed inn that faces the sea wind head-on; the rooms are loud, the beds are good, and the fire is always lit."
      },
      {
        "name": "The Wind & Wave Tavern",
        "type": "Tavern",
        "description": "A sailor's tavern that never closes; shifts end at all hours and someone is always buying a round."
      },
      {
        "name": "The Windhall Barracks",
        "type": "Barracks",
        "description": "A fortified coastal garrison protecting the harbour road; its soldiers double as tide-watchers during storm season."
      }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
