  "x775_y425": {
    "coordinate": "x775_y425",
    "biome": "Coastal",
    "kingdom": "Feldarún",
    "zone": "City",
    "cityVillage": "Grothmar",
    "description": "A dwarven coastal stronghold carved into the bluffs above the sea. Grothmar serves as Feldarún's sole outlet to the ocean — its docks are hewn from solid stone and built to outlast any storm.",
    "establishments": [
      {
        "name": "The Iron Tide Tavern",
        "type": "Tavern",
        "description": "A low-ceilinged stone hall where dock workers and ship crews drink salted ale and argue about tides."
      },
      {
        "name": "The Bluff Rock Inn",
        "type": "Inn",
        "description": "A wind-battered inn cut into the cliff face, offering functional rooms and an unobstructed view of the ocean."
      },
      {
        "name": "Grothmar Harbour",
        "type": "Harbour",
        "description": "Stone quays hewn directly into the bluffs, built to berth heavy-hulled ore-carriers and weather any storm the coast throws."
      },
      {
        "name": "The Anchor Smithy",
        "type": "Blacksmith",
        "description": "A coastal forge producing ship anchors, iron fittings, and salt-treated weapons for Feldarún's maritime trade."
      },
      {
        "name": "The Dockyard Market",
        "type": "Market",
        "description": "A weathered market at the cliff-base where sailors trade ore, preserved rations, and navigational tools under grey skies."
      }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
