    "biome": "Mountains",
    "kingdom": "Feldarún",
    "zone": "Village",
    "cityVillage": "Molgrin's Deep",
    "description": "A quiet mining village with a haunting tale of a buried beast beneath its deepest shaft.",
    "establishments": [
        {
            "name": "The Deep Tap",
            "type": "Tavern",
            "description": "A miners' tavern carved into the rock; perpetually smoky."
        },
        {
            "name": "Deep Provisions",
            "type": "General Store",
            "description": "Picks, ropes, lanterns, and emergency food rations."
        },
        {
            "name": "The Shaft Smithy",
            "type": "Blacksmith",
            "description": "A rough forge producing reinforced mining equipment and replacement tools for the shafts below the village."
        }
    ],
