  "x800_y375": {
    "coordinate": "x800_y375",
    "biome": "Mountains",
    "kingdom": "Feldarún",
    "zone": "City",
    "cityVillage": "Brondrak Kazel",
    "description": "Translates to “Hammer’s Heart.” A deep-delving citadel where the Great Anvil of the Mountain King rests.",
    "establishments": [
        {
            "name": "The Kazel Inn",
            "type": "Inn",
            "description": "A large inn catering to miners, traders, and the occasional bounty hunter."
        },
        {
            "name": "The Kazel Forge Bar",
            "type": "Tavern",
            "description": "Blacksmiths drink free if they've worked that day; everyone else pays double."
        },
        {
            "name": "Kazel Grand Forge",
            "type": "Blacksmith",
            "description": "One of the largest working forges in Feldarún."
        },
        {
            "name": "Brondrak Weapons House",
            "type": "Weaponsmith",
            "description": "Specialised in heavy weapons: war hammers, axes, and mauls."
        },
        {
            "name": "Brondrak Kazel Market",
            "type": "Market",
            "description": "Ore, metal goods, and secondhand equipment traded daily."
        },
        {
            "name": "Temple of the Anvil",
            "type": "Temple",
            "description": "A dwarven-style temple; the sound of hammering is part of the service."
        },
        {
            "name": "Kazel Compounds",
            "type": "Alchemist",
            "description": "Explosives, fireworks, and alchemical substances for industrial use."
        },
        {
            "name": "Kazel Smithing Brotherhood",
            "type": "Guild Hall",
            "description": "The most powerful guild in Feldarún; controls all metalwork pricing."
        },
        {
            "name": "Kazel Draft Stables",
            "type": "Stable",
            "description": "Heavy draught animals for the mines and forges."
        }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
