  "x900_y275": {
    "coordinate": "x900_y275",
    "biome": "Mountains",
    "kingdom": "Nithrond",
    "zone": "City",
    "cityVillage": "Namorelith",
    "description": "Perched on cliffs above the ocean, known for its wind harps that play melodies through natural stone arches.",
    "establishments": [
        {
            "name": "The Namorelith Wayhouse",
            "type": "Inn",
            "description": "A grand old coaching inn with stables for twenty horses."
        },
        {
            "name": "The Shimmering Reed",
            "type": "Tavern",
            "description": "Named for the enchanted reeds that grow in the nearby marsh."
        },
        {
            "name": "Namorelith Smithcraft",
            "type": "Blacksmith",
            "description": "Solid blades and a specialist line of marsh-adapted tools."
        },
        {
            "name": "Namorelith Market",
            "type": "Market",
            "description": "Daily trade in forest goods, dyed cloth, and carved woodwork."
        },
        {
            "name": "Temple of the Veiled Moon",
            "type": "Temple",
            "description": "A moon deity's temple; healers and scholars gather here."
        },
        {
            "name": "Namorelith Mixtures",
            "type": "Alchemist",
            "description": "Potions, powders, and marsh-plant extracts."
        },
        {
            "name": "Nithrond Rangers' Lodge",
            "type": "Guild Hall",
            "description": "Trackers, scouts, and monster-hunters available for hire."
        },
        {
            "name": "Namorelith Stables",
            "type": "Stable",
            "description": "Horses and marsh-ponies bred for swamp travel."
        }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
