  "x900_y325": {
    "coordinate": "x900_y325",
    "biome": "Hills",
    "kingdom": "Nithrond",
    "zone": "CapitalCity",
    "cityVillage": "Thalorion",
    "description": "A majestic city nestled in a crescent valley, its buildings carved from shimmering white stone and grown from enchanted roots.",
    "establishments": [
      {
        "name": "The Silver Hall",
        "type": "Temple",
        "description": "The elven grand hall of Nithrond."
      },
      {
        "name": "The Grand Archives",
        "type": "Library",
        "description": "The largest library in all of Estranta. Full of lore, ancient texts, and any information one could dream of. Access is strictly forbidden to all except members of the Elven Loremaster’s Society"
      },
      {
        "name": "The Crescent Vale Inn",
        "type": "Inn",
        "description": "A serene inn of pale stone and silk curtains, where guests sleep in curved rooms overlooking the valley’s night-blooming gardens."
      },
      {
        "name": "The Root-Wine House",
        "type": "Tavern",
        "description": "An elven tavern carved into the base of an enchanted root cluster, serving aged root-wines and moonlit spirits."
      },
      {
        "name": "The Moonguard Barracks",
        "type": "Barracks",
        "description": "Thalorion’s garrison of silver-armoured moonguards who patrol the crescent valley and enforce the city’s strict laws of passage."
      },
      {
        "name": "The Verdant Exchange",
        "type": "Market",
        "description": "A market of sculpted white stone stalls where enchanted cloth, crystallised herbs, and rare mineral dyes are traded."
      },
      {
        "name": "The Loremaster’s Guild",
        "type": "Guild",
        "description": "The seat of Nithrond’s scholar-guild, where knowledge is traded as currency and membership is nearly impossible to obtain."
      },
      {
        "name": "The Spellweave Tower",
        "type": "Mage Tower",
        "description": "A tower of moonwhite marble where Nithrond’s spellweavers perfect the craft of light-binding and memory enchantment."
      }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
  "x900_y350": {
    "coordinate": "x900_y350",
    "biome": "Forest",
    "kingdom": "Nithrond",
    "zone": "Village",
    "cityVillage": "Elmyralen",
    "description": " quiet village nestled within flowering groves, where the trees whisper tales of the past to those who listen.",
    "establishments": [
        {
            "name": "The Elmyralen Root Cellar",
            "type": "Tavern",
            "description": "A below-ground tavern; cool and earthy year-round."
        },
        {
            "name": "Elmyralen Provisions",
            "type": "General Store",
            "description": "Dried herbs, preserved mushrooms, and travelling supplies."
        },
        {
            "name": "The Bloom-Root Herbalist",
            "type": "Herbalist",
            "description": "A grove healer's cottage where flowering herb bundles hang from every rafter and remedies are prepared by candlelight."
        }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
