  "x950_y75": {
    "coordinate": "x950_y75",
    "biome": "Forest",
    "kingdom": "Naradreth",
    "zone": "City",
    "cityVillage": "Draes'ythil",
    "description": "Known as the “Sister of Silence,” this solemn city is a seat of old magic and home to a revered order of seers. No one speaks aloud here—communication is done via telepathic glyphs.",
    "establishments": [
        {
            "name": "The Night Lodge",
            "type": "Inn",
            "description": "A city inn built for the constant stream of traders and adventurers."
        },
        {
            "name": "The Shadowed Arch",
            "type": "Tavern",
            "description": "A cave-like tavern beneath an ancient stone arch."
        },
        {
            "name": "Draes'ythil Blades",
            "type": "Blacksmith",
            "description": "Known for lightweight, swift swords; a favourite of rangers and scouts."
        },
        {
            "name": "Draes'ythil Trade Precinct",
            "type": "Market",
            "description": "A trade zone dedicated to goods from the deep wastes."
        },
        {
            "name": "Temple of the Hidden Path",
            "type": "Temple",
            "description": "Worshippers seek guidance in dark times; the priests speak in riddles."
        },
        {
            "name": "Void Compounds",
            "type": "Alchemist",
            "description": "Dangerous but effective compounds for the desperate or reckless."
        },
        {
            "name": "Naradreth Scouts' Guild",
            "type": "Guild Hall",
            "description": "The finest wilderness guides available; prices reflect their expertise."
        },
        {
            "name": "Draes'ythil Stables",
            "type": "Stable",
            "description": "Horses conditioned for the harsh Naradreth terrain."
        }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
