  "x950_y450": {
    "coordinate": "x950_y450",
    "biome": "Forest",
    "kingdom": "Nithrond",
    "zone": "City",
    "cityVillage": "Caeleth",
    "description": "Surrounded by autumnal forests, this city is famed for its amber-leafed gardens and moonstone roads.",
    "establishments": [
        {
            "name": "The Caeleth Spire Inn",
            "type": "Inn",
            "description": "In the tallest building in the city; views stretch to the horizon."
        },
        {
            "name": "The Duskwood Bar",
            "type": "Tavern",
            "description": "Dark timber and low light; intimate and slightly mysterious."
        },
        {
            "name": "Caeleth Armoury",
            "type": "Blacksmith",
            "description": "City-contract weapons and armour; public sales permitted."
        },
        {
            "name": "Caeleth Grand Market",
            "type": "Market",
            "description": "A large market dealing in forest goods, minerals, and exotic imports."
        },
        {
            "name": "Temple of the Ancient Deep",
            "type": "Temple",
            "description": "A temple to old powers; attended by scholars as much as worshippers."
        },
        {
            "name": "The Deep Vial",
            "type": "Alchemist",
            "description": "Unusual compounds from Nithrond's strange mineral deposits."
        },
        {
            "name": "Caeleth Commerce Circle",
            "type": "Guild Hall",
            "description": "Oversees all major trade in eastern Nithrond."
        },
        {
            "name": "Caeleth Stables",
            "type": "Stable",
            "description": "Forest-trained horses; also guides available for the deep woods."
        },
        {
            "name": "Caeleth Assembly Hall",
            "type": "Town Hall",
            "description": "The city council meets publicly; all citizens may address the floor."
        }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
