  "x975_y125": {
    "coordinate": "x975_y125",
    "biome": "Forest",
    "kingdom": "Naradreth",
    "zone": "CapitalCity",
    "cityVillage": "Velra'syr",
    "description": "The Veiled Crown of Naradreth. The capital city of Naradreth. Though it appears as one city, Velra’syl is divided into twelve distinct noble districts, each ruled by one of the Twelve Great Houses. These districts reflect the unique traditions, magic, and architecture of their ruling clans. At its center stands the Circle of Spires, where the houses meet to govern. Outsiders are rarely welcome, and most never see beyond the outer walls.",
    "establishments": [
      {
        "name": "Sunspire Tower",
        "type": "Other",
        "description": "An ancient observatory where the elves study the stars and celestial movements."
      },
      {
        "name": "The House of Twelve Veils",
        "type": "Inn",
        "description": "One wing of the Twelve House district permits outsiders to lodge here, in austere rooms watched by silent House retainers."
      },
      {
        "name": "The Amber Spire",
        "type": "Mage Tower",
        "description": "The tallest of the Circle of Spires, where Naradreth's arch-mages convene to regulate magical practice across the Twelve Houses."
      },
      {
        "name": "The House Vaults",
        "type": "Library",
        "description": "Each Great House maintains a vault of restricted lore; the public wing holds only approved texts and approved visitors."
      },
      {
        "name": "The Inner Market",
        "type": "Market",
        "description": "A tightly controlled bazaar where only goods meeting House standards may be traded; counterfeit wares vanish without explanation."
      },
      {
        "name": "The Silent Barracks",
        "type": "Barracks",
        "description": "The collective garrison of the Twelve Great Houses, staffed by oath-sworn soldiers who speak only when addressed by a House lord."
      },
      {
        "name": "The Shadowstitch Guild",
        "type": "Thieves Guild",
        "description": "Allegedly fictional; in practice, every major House is aware of it and employs its agents for tasks that must not be traced."
      },
      {
        "name": "The House Alchemist",
        "type": "Alchemist",
        "description": "A licensed alchemist serving all Twelve Houses, their formulas proprietary and their silence guaranteed by compact."
      }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
