  "x975_y175": {
    "coordinate": "x975_y175",
    "biome": "Coastal",
    "kingdom": "Naradreth",
    "zone": "City",
    "cityVillage": "Ilryndor",
    "description": "A shadowed harbor city with black sails and moonlit docks, heavily patrolled by the Silent Guard. Known for the elite naval academy training sea-hunters and storm-scryers.",
    "establishments": [
        {
            "name": "The Ilryndor Way Inn",
            "type": "Inn",
            "description": "A stone inn on the ancient pilgrim road."
        },
        {
            "name": "The Rune Bench",
            "type": "Tavern",
            "description": "Strange carvings cover every surface; the origins are unknown."
        },
        {
            "name": "Ilryndor Smithing House",
            "type": "Blacksmith",
            "description": "Produces tools and weapons adapted for desert and ruin exploration."
        },
        {
            "name": "Ilryndor Relic Market",
            "type": "Market",
            "description": "Ancient artefacts, ruin salvage, and strange curios."
        },
        {
            "name": "Temple of the Ruined Age",
            "type": "Temple",
            "description": "Dedicated to memory and the preservation of lost civilisations."
        },
        {
            "name": "Ilryndor Compounds",
            "type": "Alchemist",
            "description": "Specialises in preservation, illumination, and ruin-adapted substances."
        },
        {
            "name": "Ilryndor Ruin Explorers' Guild",
            "type": "Guild Hall",
            "description": "Contracts for ruin surveying, artefact recovery, and escort."
        },
        {
            "name": "Ilryndor Stables",
            "type": "Stable",
            "description": "Desert-conditioned horses; expensive but worth it."
        },
        {
            "name": "Ilryndor Archive of Ruins",
            "type": "Library",
            "description": "The best resource for identifying ancient artefacts and lost languages."
        },
        {
            "name": "Ilryndor Council of Ages",
            "type": "Town Hall",
            "description": "Governs by consensus; every citizen of age has a vote."
        }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
