  "x1000_y350": {
    "coordinate": "x1000_y350",
    "biome": "Forest",
    "kingdom": "Nithrond",
    "zone": "City",
    "cityVillage": "Sylvaen",
    "description": "A gleaming city built into and around towering silver-bark trees, known for its elevated walkways and glowing crystal lanterns.",
    "establishments": [
        {
            "name": "The Sylvaen Lodge",
            "type": "Inn",
            "description": "A grand wooden inn constructed from the ancient forest's fallen timber."
        },
        {
            "name": "The Green Hall",
            "type": "Tavern",
            "description": "An enormous forest tavern capable of hosting a hundred guests."
        },
        {
            "name": "Sylvaen Irongrove",
            "type": "Blacksmith",
            "description": "Where iron meets wood; furniture-fittings and forest-tools are the speciality."
        },
        {
            "name": "Sylvaen Forest Market",
            "type": "Market",
            "description": "Weekly market for forest products, crafted goods, and forest-gathered items."
        },
        {
            "name": "Temple of the Living Forest",
            "type": "Temple",
            "description": "The most sacred site in Nithrond; the forest speaks through the priests."
        },
        {
            "name": "The Grove Vial",
            "type": "Alchemist",
            "description": "Forest-essence compounds of unusual potency."
        },
        {
            "name": "Sylvaen Woodwrights' Guild",
            "type": "Guild Hall",
            "description": "Manages timber rights, carpentry contracts, and forest use."
        },
        {
            "name": "Forest-Edge Stables",
            "type": "Stable",
            "description": "Horses bred to navigate dense forest terrain."
        },
        {
            "name": "Sylvaen Forest Library",
            "type": "Library",
            "description": "An archive of Nithrond's history, ecology, and magical lore."
        },
        {
            "name": "Sylvaen Council of Trees",
            "type": "Town Hall",
            "description": "The city's governing body meets surrounded by living trees trained into the architecture."
        }
    ],
    "pointsOfInterest": [],
    "discovered": false
  },
